// Handler creates http.Handler with routing matching OpenAPI spec.
func Handler(si ServerInterface) http.Handler {
	return HandlerWithOptions(si, ChiServerOptions{})
}

type ChiServerOptions struct {
	BaseURL          string
	BaseRouter       chi.Router
	Middlewares      []MiddlewareFunc
	ErrorHandlerFunc func(w http.ResponseWriter, r *http.Request, err error)
}

// HandlerFromMux creates http.Handler with routing matching OpenAPI spec based on the provided mux.
func HandlerFromMux(si ServerInterface, r chi.Router) http.Handler {
	return HandlerWithOptions(si, ChiServerOptions{
		BaseRouter: r,
	})
}

func HandlerFromMuxWithBaseURL(si ServerInterface, r chi.Router, baseURL string) http.Handler {
	return HandlerWithOptions(si, ChiServerOptions{
		BaseURL:    baseURL,
		BaseRouter: r,
	})
}

// HandlerWithOptions creates http.Handler with additional options
func HandlerWithOptions(si ServerInterface, options ChiServerOptions) http.Handler {
	r := options.BaseRouter

	if r == nil {
		r = chi.NewRouter()
	}
	if options.ErrorHandlerFunc == nil {
		options.ErrorHandlerFunc = func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusBadRequest)
		}
	}
	wrapper := ServerInterfaceWrapper{
		Handler:            si,
		HandlerMiddlewares: options.Middlewares,
		ErrorHandlerFunc:   options.ErrorHandlerFunc,
	}

	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/mail/accounts", wrapper.ListMailAccounts)
	})
	r.Group(func(r chi.Router) {
		r.Post(options.BaseURL+"/mail/accounts", wrapper.CreateMailAccount)
	})
	r.Group(func(r chi.Router) {
		r.Delete(options.BaseURL+"/mail/accounts/{accountId}", wrapper.DeleteMailAccount)
	})
	r.Group(func(r chi.Router) {
		r.Patch(options.BaseURL+"/mail/accounts/{accountId}", wrapper.UpdateMailAccount)
	})
	r.Group(func(r chi.Router) {
		r.Post(options.BaseURL+"/mail/accounts/{accountId}/sync", wrapper.SyncMailAccount)
	})
	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/mail/messages", wrapper.ListMailMessages)
	})
	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/mail/messages/{messageId}", wrapper.GetMailMessage)
	})
	r.Group(func(r chi.Router) {
		r.Patch(options.BaseURL+"/mail/messages/{messageId}", wrapper.UpdateMailMessage)
	})
	r.Group(func(r chi.Router) {
		r.Post(options.BaseURL+"/mail/messages/batch", wrapper.BatchMailMessages)
	})
	r.Group(func(r chi.Router) {
		r.Post(options.BaseURL+"/mail/read-all", wrapper.MarkAllMailRead)
	})
	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/mail/messages/{messageId}/attachments/{index}", wrapper.DownloadMailAttachment)
	})
	r.Group(func(r chi.Router) {
		r.Post(options.BaseURL+"/mail/messages/{messageId}/triage", wrapper.TriageMailMessage)
	})
	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/mail/todo", wrapper.ListMailTodo)
	})
	r.Group(func(r chi.Router) {
		r.Put(options.BaseURL+"/mail/messages/{messageId}/done", wrapper.SetMailDone)
	})
	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/mail/summary", wrapper.GetMailSummary)
	})

	return r
}
